(() => {
  'use strict';
  const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const elementClass=v=>({'목':'wood','화':'fire','토':'earth','금':'metal','수':'water'}[v]||'');
  const heading=(caption,title)=>`<div class="report-section-heading"><div><h3>${e(title)}</h3></div></div>`;
  const narrative=chapters=>`<div class="astro-narrative">${(chapters||[]).map((c,i)=>`<details class="astro-chapter reading-fold" data-reading-fold ${i===0?'open':''}><summary><h3>${e(c.title)}</h3><span class="fold-mark" aria-hidden="true">+</span></summary>${c.paragraphs.map(p=>`<p>${e(p)}</p>`).join('')}${c.basis?`<details class="chapter-evidence"><summary>이 항목의 계산 근거</summary><p>${e(c.basis)}</p></details>`:''}</details>`).join('')}</div>`;
  function hanjaName(n){
    if(!n.hanja_provided)return `<div class="missing-analysis"><h4>이름 한자를 알면 뜻도 함께 읽어요.</h4><p>‘다시 입력하기’에서 이름 글자별로 한자를 고르면 뜻도 볼 수 있어요. 사주는 이름 한자 없이도 볼 수 있습니다.</p></div>`;
    return `<section class="report-section">${heading('THE MEANING IN YOUR NAME','‘'+n.name_hanja+'’에 담긴 뜻')}<div class="hanja-name-grid">${n.hanja.map(h=>`<article><b>${e(h.character)}</b><span>${e(h.meaning||(h.verified?'원자료 뜻 확인':'사전 뜻 미확인'))}</span><small>${e(h.readings.join(' · ')||'독음 미확인')} · 입력 ${e(h.syllable)}</small>${h.reading_matches===false?'<p>확인한 독음과 달라요. 두음법칙 등 예외를 함께 확인해 주세요.</p>':''}</article>`).join('')}</div><p class="report-description">${e(n.hanja_explanation)}</p><details class="method-detail"><summary>한자 사전의 원자료와 확인 범위 <span>+</span></summary>${n.hanja.map(h=>`<p><b>${e(h.character)}</b> · ${e(h.definition||'등록된 뜻이 없어 생성하지 않았어요.')}</p>`).join('')}<p>Unicode 17.0.0 Unihan의 뜻과 독음을 사용해요. 한국어 기본 뜻은 모아의 정리이며, 일반 사전의 뜻을 작명 원획·자원오행·81수리의 판정으로 바꾸지 않습니다.</p></details></section>`;
  }
  function astrology(r){
    const a=r.astrology;
    if(!a)return '';
    const sun=a.sun,moon=a.moon,c=r.comparison;
    const signText=p=>p.sign_confirmed?e(p.sign):(p.possible_signs||[]).map(e).join(' / ');
    return `<section class="report-section">${heading('THE SKY AT YOUR BIRTH','태어난 날의 하늘')}<p class="report-description">입력한 생일로 별자리도 살펴봤어요. 태양은 나를 표현하는 방식, 달은 편안함을 느끼는 방식으로 읽어요.</p><div class="sky-summary"><article><span class="report-overline">태양 · 나를 표현하는 방식</span><h4>${signText(sun)}</h4><p>${sun.sign_confirmed?e(sun.symbol)+'의 상징으로 읽어요.':'이날은 별자리 경계를 지나요. 정확한 출생 시간을 확인해 주세요.'}</p><small>${e(sun.reference)}</small></article><article><span class="report-overline">달 · 마음이 편한 방식</span><h4>${moon?e(moon.sign):'시간을 알려주세요'}</h4><p>${moon?e(moon.symbol)+'의 상징으로 읽어요.':'출생 시간이 없어 달의 위치를 확정하지 않았어요.'}</p><small>${moon?'출생 시각 기준':'시간 입력 시 함께 계산'}</small></article></div><p class="fold-help">여러 천체를 함께 읽은 종합 해석이에요. 성격·일·관계·주의할 점을 차례로 살펴봐요.</p>${a.interpretation?.length?narrative(a.interpretation.filter(c=>c.topic!=='aspects')):r.generation?'<p>같은 출생 정보로 별자리의 개인 풀이도 읽을 수 있어요.</p><button class="button" data-additional-service="stars">별자리 풀이도 읽어보기</button>':'<p role="status">계산된 별자리의 자세한 풀이를 작성하고 있어요.</p>'}<p class="report-footnote">별자리의 상징은 나를 돌아보는 관점이에요. 실제 성격이나 감정의 진단은 아닙니다.</p></section><details class="astro-calculations"><summary>천체 위치와 자세한 계산 보기 <span>+</span></summary><section class="report-section">${heading('PLANETARY POSITIONS','천체별 위치와 읽는 관점')}<div class="planet-table-wrap"><table class="planet-table"><caption class="visually-hidden">천체의 열대황도 별자리와 구간 내 각도</caption><thead><tr><th scope="col">천체</th><th scope="col">별자리 · 구간 내 각도</th><th scope="col">읽는 관점</th></tr></thead><tbody>${a.positions.map(p=>`<tr><th scope="row">${e(p.label)}</th><td>${signText(p)} <small>${e(p.degree_in_sign)}°${!a.hour_known?' · 정오':''}</small></td><td>${e(p.role)}</td></tr>`).join('')}</tbody></table></div><p class="report-footnote">각도는 각 30° 별자리 구간 안의 위치예요.${!a.hour_known?' 시간이 없으면 정오 참고 위치이며, 하루 중 별자리가 바뀌는 천체는 가능한 구간을 함께 표시했어요.':''} 외행성의 위치는 같은 시기에 태어난 여러 사람이 공유할 수 있어요.</p><details class="method-detail"><summary>천체 계산 기준과 전체 황경 <span>+</span></summary><p>${e(a.method)}</p><p>태양은 SunPosition, 달은 EclipticGeoMoon, 행성은 광행차를 보정한 지심 좌표를 날짜 기준 황도로 변환했어요. 한국표준시 UTC+9 기준이며 역사적 서머타임은 별도 확인이 필요해요.</p><div class="weight-list">${a.positions.map(p=>`<span>${e(p.label)} <b>${e(p.longitude)}°</b></span>`).join('')}</div></details></section><section class="report-section">${heading('ANGLES BETWEEN BODIES','천체 사이의 각도')}${narrative((a.interpretation||[]).filter(c=>c.topic==='aspects'))}${a.hour_known?`<div class="aspect-list">${a.aspects.length?a.aspects.map(v=>`<article><div><b>${e(v.left)} · ${e(v.right)}</b><span>${e(v.name)} ${v.angle}°</span></div><p>${e(v.meaning)}예요.</p><small>실제 황경 차이 ${v.separation}° · 기준각과의 차이 ${v.orb}°</small></article>`).join(''):'<p class="report-description">이 허용 범위에서 검출한 주요 각도가 없어요.</p>'}</div><p class="report-footnote">합 0° · 육분 60° · 사각 90° · 삼분 120° · 대립 180°. 모든 쌍에 기준각 ±${a.aspect_orb}°를 적용했어요. 유파마다 허용 범위가 다르며 운세 점수가 아닙니다.</p>`:'<div class="missing-analysis"><h4>정확한 시간을 알면 함께 볼 수 있어요.</h4><p>정오의 각도를 실제 출생 시각의 관계로 안내하지 않도록, 천체 각도는 생략했어요.</p></div>'}</section></details><details class="astro-comparison report-section"><summary>사주와 함께 읽고 싶다면</summary>${heading('TWO WAYS TO READ',c.title)}<div class="comparison-grid"><article><span>사주에서 읽은 것</span><p>${e(c.saju)}</p></article><article><span>점성술에서 읽은 것</span><p>${e(c.astrology)}</p></article></div><div class="reflection"><span>함께 읽는 질문</span><p>${e(c.reflection)}</p></div><p class="report-footnote">${e(c.note)}</p></details><details class="method-detail"><summary>별자리 분석 범위</summary><p>${e(a.scope)}</p></details>`;
  }
  function name(r){
    const n=r.name_analysis;
    if(r.naming)return window.MoaNaming.render(r.naming);
    if(!n)return '';
    if(!n.available)return `<section class="report-section">${heading('YOUR NAME, SAME REPORT','이름도 함께 살펴볼 수 있어요.')}<p class="report-description">${e(n.reason)} 아래의 ‘다시 입력하기’에서 이름만 추가해 주세요.</p></section>`;
    return `${hanjaName(n)}<section class="report-section">${heading('A NAME YOU CALL EVERY DAY','‘'+n.display_name+'’의 소리 구성')}<p class="report-description">같은 입력에 담긴 이름을 함께 살펴봤어요. 이름 부분은 ${n.syllables}음절이며, 성과 구분해 초성을 계산했어요.</p><div class="name-syllables">${n.letters.map(l=>`<article><b>${e(l.syllable)}</b><span>초성 ${e(l.initial)}</span><small class="${elementClass(l.element)}">${e(l.element)} 오행</small></article>`).join('')}</div><p class="report-footnote">${e(n.method)}. 한 가지 전통 분류이며 뜻이나 길흉을 정한 결과는 아닙니다.</p><div class="reflection"><span>이름을 직접 불러보기</span><p>‘${e(n.display_name)}’을 천천히, 또 평소 속도로 불러보세요. 이름만 부를 때와 성을 붙일 때의 소리를 함께 들어보세요.</p></div><a class="name-stat-link" href="https://www.namechart.kr/name/${encodeURIComponent(n.name)}" target="_blank" rel="noopener noreferrer">‘${e(n.name)}’의 이름 통계 확인하기 ↗</a><p class="report-footnote">네임차트의 공개 페이지로 이동해요. 통계나 순위를 이 리포트에서 생성하지 않습니다.</p></section><section class="report-section">${heading('NAMING WITH A BIRTH CHART','사주와 이름은 이렇게 연결해요.')}<p class="report-description">${r.balance.available?`사주에서 선택된 용신은 ${e(r.balance.yong_element||'미선정')}, 적용 방식은 ${e(r.balance.yong_method)}이에요.`:'출생 시간이 없어 용신은 확정하지 않았어요.'} 이름의 초성 분류를 이와 나란히 확인할 수 있지만, 소리만으로 용신을 보완했다거나 좋은 이름이라고 판정하지는 않아요.</p><div class="missing-analysis"><h4>사전 뜻과 전문 작명의 판단은 구분해요.</h4><p>${e(n.scope)}</p></div></section>`;
  }
  function overview(r){
    if(!r.overview)return '';
    return `<div class="profile-overview">${r.overview.map(o=>`<article><span>${e(o.label)}</span><b>${e(o.value)}</b><small>${e(o.detail)}</small></article>`).join('')}</div><details class="input-coverage"><summary>입력 정보로 어디까지 확인했나요? <span>+</span></summary><div>${r.input_coverage.map(c=>`<p><b>${e(c.label)} <small>${e(c.status)}</small></b><span>${e(c.text)}</span></p>`).join('')}<p><b>년지의 띠</b><span>${e(r.year_symbol.animal)} · ${e(r.year_symbol.branch)}. ${e(r.year_symbol.method)}으로, 설날이나 양력 연도 기준과 차이가 날 수 있어요.</span></p></div></details>`;
  }
  window.MoaProfile={overview,astrology,name,hanjaName};
})();
